    bronze_thermocouplesheath = { name = "Bronast zaščita termoelementov", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast zaščita termoelementov za livarje." },
    silver_thermocouplesheath = { name = "Srebrn zaščita termoelementov", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn zaščita termoelementov za livarje." },
