    jewel_set_thermocouplesheath = { name = "Draguljast zaščita termoelementov", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast zaščita termoelementov za livarje." },
