ThermocoupleSheathMaker.ironStock=18; ThermocoupleSheathMaker.bronzeStock=14; ThermocoupleSheathMaker.woodStock=10; ThermocoupleSheathMaker.leatherStock=8; ThermocoupleSheathMaker.silverStock=8; ThermocoupleSheathMaker.goldStock=6; ThermocoupleSheathMaker.jewelStock=4; ThermocoupleSheathMaker.pearlStock=4
ThermocoupleSheathMaker.productStock = {}; ThermocoupleSheathMaker.buildings = {}; ThermocoupleSheathMaker.maker = nil; ThermocoupleSheathMaker.activeMaking = {}; ThermocoupleSheathMaker.totalProducts = 0; ThermocoupleSheathMaker.dayTimer = 0
function ThermocoupleSheathMaker.init() ThermocoupleSheathMaker.ironStock=18; ThermocoupleSheathMaker.bronzeStock=14; ThermocoupleSheathMaker.woodStock=10; ThermocoupleSheathMaker.leatherStock=8; ThermocoupleSheathMaker.silverStock=8; ThermocoupleSheathMaker.goldStock=6; ThermocoupleSheathMaker.jewelStock=4; ThermocoupleSheathMaker.pearlStock=4; ThermocoupleSheathMaker.productStock={}; ThermocoupleSheathMaker.buildings={}; ThermocoupleSheathMaker.maker=nil; ThermocoupleSheathMaker.activeMaking={}; ThermocoupleSheathMaker.totalProducts=0; ThermocoupleSheathMaker.dayTimer=0; print("[ThermocoupleSheathMaker] Royal Thermocouple Sheath Maker System initialized (6 products, 4 buildings)") end
function ThermocoupleSheathMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ThermocoupleSheathMaker.maker={name=n or ("Zaščitkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zaščitkar najet: %s (spretnost: %d)",ThermocoupleSheathMaker.maker.name,s),"success") end; return true end
function ThermocoupleSheathMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ThermocoupleSheathMaker.build(id) local ok,e=ThermocoupleSheathMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ThermocoupleSheathMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ThermocoupleSheathMaker.getQualityBonus() local b=0; for _,bd in ipairs(ThermocoupleSheathMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ThermocoupleSheathMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ThermocoupleSheathMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ThermocoupleSheathMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ThermocoupleSheathMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ThermocoupleSheathMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ThermocoupleSheathMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ThermocoupleSheathMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ThermocoupleSheathMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ThermocoupleSheathMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ThermocoupleSheathMaker.buildings==0 then return false,"Potrebna zaščitna delavnica" end; if not ThermocoupleSheathMaker.maker then return false,"Potreben zaščitkar" end; return true end
function ThermocoupleSheathMaker.make(pt,qty) qty=qty or 1; local ok,e=ThermocoupleSheathMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ThermocoupleSheathMaker.ironStock=ThermocoupleSheathMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ThermocoupleSheathMaker.bronzeStock=ThermocoupleSheathMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ThermocoupleSheathMaker.woodStock=ThermocoupleSheathMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ThermocoupleSheathMaker.leatherStock=ThermocoupleSheathMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ThermocoupleSheathMaker.silverStock=ThermocoupleSheathMaker.silverStock-d.silverCost*qty end; if d.goldCost then ThermocoupleSheathMaker.goldStock=ThermocoupleSheathMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ThermocoupleSheathMaker.jewelStock=ThermocoupleSheathMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ThermocoupleSheathMaker.pearlStock=ThermocoupleSheathMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ThermocoupleSheathMaker.maker then t=math.max(1,t-math.floor(ThermocoupleSheathMaker.maker.skill/13)) end; table.insert(ThermocoupleSheathMaker.activeMaking,{id="thermocouplesheath_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ThermocoupleSheathMaker.completeMaking(m) local q=1.0+(ThermocoupleSheathMaker.getQualityBonus()/100); if ThermocoupleSheathMaker.maker then q=q+(ThermocoupleSheathMaker.maker.skill/140) end; q=math.min(2.5,q); ThermocoupleSheathMaker.productStock[m.productType]=(ThermocoupleSheathMaker.productStock[m.productType] or 0)+m.quantity; ThermocoupleSheathMaker.totalProducts=ThermocoupleSheathMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ThermocoupleSheathMaker.maker then ThermocoupleSheathMaker.maker.itemsMade=ThermocoupleSheathMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ThermocoupleSheathMaker.maker.skill=math.min(100,ThermocoupleSheathMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zaščita izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"thermocouplesheath.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ThermocoupleSheathMaker.update(dt) if not _G.state then return end; ThermocoupleSheathMaker.dayTimer=ThermocoupleSheathMaker.dayTimer+dt; if ThermocoupleSheathMaker.dayTimer>=30 then ThermocoupleSheathMaker.dayTimer=0; for i=#ThermocoupleSheathMaker.activeMaking,1,-1 do local m=ThermocoupleSheathMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ThermocoupleSheathMaker.completeMaking(m); table.remove(ThermocoupleSheathMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ThermocoupleSheathMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ThermocoupleSheathMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ThermocoupleSheathMaker.getStats() return {ironStock=ThermocoupleSheathMaker.ironStock,bronzeStock=ThermocoupleSheathMaker.bronzeStock,woodStock=ThermocoupleSheathMaker.woodStock,leatherStock=ThermocoupleSheathMaker.leatherStock,silverStock=ThermocoupleSheathMaker.silverStock,goldStock=ThermocoupleSheathMaker.goldStock,jewelStock=ThermocoupleSheathMaker.jewelStock,pearlStock=ThermocoupleSheathMaker.pearlStock,productStock=ThermocoupleSheathMaker.productStock,numBuildings=#ThermocoupleSheathMaker.buildings,hasMaker=ThermocoupleSheathMaker.maker~=nil,makerName=ThermocoupleSheathMaker.maker and ThermocoupleSheathMaker.maker.name or "—",makerSkill=ThermocoupleSheathMaker.maker and ThermocoupleSheathMaker.maker.skill or 0,activeMaking=#ThermocoupleSheathMaker.activeMaking,totalProducts=ThermocoupleSheathMaker.totalProducts} end
return ThermocoupleSheathMaker
